#ifndef OF_UNICODE_H
#define OF_UNICODE_H

#include <stdint.h>

#include "of_unicode_enums.h"

/* OF_GC_*: Cn for an unassigned codepoint or one past U+10FFFF */
unsigned of_uni_category(uint32_t cp);

/* the canonical combining class, 0 for a starter */
unsigned of_uni_combining_class(uint32_t cp);

/* Default_Ignorable_Code_Point */
int of_uni_default_ignorable(uint32_t cp);

/* OF_SCRIPT_* (Scripts.txt) */
unsigned of_uni_script(uint32_t cp);

/* One step of cp's canonical decomposition: 2 (a then b), 1 (a alone), or
 * 0 when it has none. Hangul syllables too. */
int of_uni_decompose(uint32_t cp, uint32_t *a, uint32_t *b);

/* The primary composite of a and b, or 0 */
uint32_t of_uni_compose(uint32_t a, uint32_t b);

static inline int of_uni_is_mark(uint32_t cp)
{
    unsigned c = of_uni_category(cp);
    return c == OF_GC_MN || c == OF_GC_MC || c == OF_GC_ME;
}

#endif
